"use strict";
const fs = require("node:fs"), path = require("node:path");
const root = path.resolve(__dirname, "../..");
const embed = (name, file) => `const ${name} = (() => {\n  const module = { exports: {} };\n${fs.readFileSync(path.join(root, file), "utf8").replace(/\r\n/g, "\n")}\n  return module.exports;\n})();\n`;
const output = `"use strict";
// Generated by node server/scripts/buildReleasePreflight.js.
// Portable read-only startup check. No database connection, writes, or secrets printed.
try { require(require.resolve("dotenv", { paths: [process.cwd()] })).config({ quiet: true }); } catch (_) {}
${embed("secrets", "server/utils/deploymentSecrets.js")}
${embed("mongo", "server/utils/mongoConnection.js")}
${embed("security", "server/utils/deploymentSecurity.js")}
function checkProductionRelease(env = process.env, nodeVersion = process.versions.node) {
  const issues = secrets.deploymentSecretIssues(env);
  const checks = { node: Number(nodeVersion.split(".")[0]) >= 20, productionMode: env.NODE_ENV === "production", secrets: issues.length === 0, databaseConfigured: Boolean(env.MONGODB_URI), databaseAuthenticated: false, databaseTransport: false };
  if (!checks.node) issues.push("Node.js 20 or newer is required.");
  if (!checks.productionMode) issues.push("Set NODE_ENV=production for the live application.");
  if (!checks.databaseConfigured) issues.push("MONGODB_URI is required in production.");
  else {
    let connection;
    try { connection = mongo.buildMongoConnectionUri(env.MONGODB_URI, { directHosts: env.MONGODB_DIRECT_HOSTS, replicaSet: env.MONGODB_REPLICA_SET, authSource: env.MONGODB_AUTH_SOURCE }).uri; }
    catch (_) { issues.push("Review the MongoDB direct-host and replica-set settings."); }
    if (connection) {
      try { security.assertAuthenticatedMongoUri(connection); checks.databaseAuthenticated = true; }
      catch (_) { issues.push("MongoDB requires an authenticated internal/TLS connection."); }
      checks.databaseTransport = mongo.isTlsProtectedMongoUri(connection) || (env.MONGODB_ALLOW_PLAINTEXT_INTERNAL === "true" && mongo.isSingleLabelMongoUri(connection));
      if (!checks.databaseTransport) issues.push("Enable MongoDB TLS, or use its private single-label Docker hostname with MONGODB_ALLOW_PLAINTEXT_INTERNAL=true.");
    }
  }
  return { ready: issues.length === 0, scope: "production startup configuration only", checks, issues };
}
if (require.main === module) {
  const result = checkProductionRelease();
  console.log(JSON.stringify(result, null, 2));
  if (!result.ready) process.exitCode = 1;
}
module.exports = { checkProductionRelease };
`;
const destination = path.join(root, "deploy/dokploy/release-preflight.cjs");
fs.mkdirSync(path.dirname(destination), { recursive: true });
fs.writeFileSync(destination, output);
console.log("Generated deploy/dokploy/release-preflight.cjs from the production startup guards.");
